import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse(`{"title":"Evaluation System","description":"Hearth's evaluation pyramid, task sets, core metrics, validators, trajectory replay, fault injection, security red teaming, and stage gates.","frontmatter":{"title":"Evaluation System","description":"Hearth's evaluation pyramid, task sets, core metrics, validators, trajectory replay, fault injection, security red teaming, and stage gates.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/evaluation.md","filePath":"en/architecture/evaluation.md","lastUpdated":1793706118000}`),r={name:"en/architecture/evaluation.md"};function n(l,e,o,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<p class="eyebrow">EVALUATION</p><h1 id="evaluation-system" tabindex="-1">Evaluation System <a class="header-anchor" href="#evaluation-system" aria-label="Permalink to &quot;Evaluation System&quot;">​</a></h1><p class="lead">A demo is not capability. The evaluation system proves the system can actually do the work through task sets, metrics, baselines, verifiers, trajectory replay, fault injection, and statistical discipline.</p><h2 id="evaluation-system-1" tabindex="-1">Evaluation System <a class="header-anchor" href="#evaluation-system-1" aria-label="Permalink to &quot;Evaluation System&quot;">​</a></h2><p>A demo is not capability. Hearth only trusts evidence that is repeatable, verifiable, and includes failure samples.</p><h3 id="evaluation-pyramid" tabindex="-1">Evaluation Pyramid <a class="header-anchor" href="#evaluation-pyramid" aria-label="Permalink to &quot;Evaluation Pyramid&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>What is evaluated</th><th>Frequency</th></tr></thead><tbody><tr><td>Unit/Tool</td><td>Parsers, connectors, policies, verifiers</td><td>Every commit</td></tr><tr><td>Task-level</td><td>Single-task end-to-end success</td><td>Every release</td></tr><tr><td>Trajectory Replay</td><td>Historical trajectory replay, route switching, and failure recovery</td><td>Continuous</td></tr><tr><td>Shadow</td><td>Real inputs, no external side effects</td><td>Continuous</td></tr><tr><td>Live Pilot</td><td>Real users, real side effects, controlled scope</td><td>Before stage advancement</td></tr><tr><td>Long-run</td><td>Multi-device residency, device switching, memory evolution</td><td>Stage acceptance</td></tr></tbody></table><h3 id="task-set" tabindex="-1">Task Set <a class="header-anchor" href="#task-set" aria-label="Permalink to &quot;Task Set&quot;">​</a></h3><p>Initially establish 40–60 real tasks covering eight task families: email, calendar, documents, research, code, web, desktop, and cross-application workflows.</p><p>Requirements:</p><ul><li>Each task has explicit inputs, acceptance criteria, and a verifier;</li><li>Include normal, boundary, failure, and malicious inputs;</li><li>Real desensitized data takes priority; synthetic data is marked separately;</li><li>Maintain a holdout set that cannot be repeatedly tuned against;</li><li>Failure samples must not be deleted;</li><li>When adding capabilities, add corresponding tasks rather than only adding demos;</li><li>The MVP&#39;s narrow task family must also have an independent task set and cannot rely on a single demo script.</li></ul><h3 id="core-metrics" tabindex="-1">Core Metrics <a class="header-anchor" href="#core-metrics" aria-label="Permalink to &quot;Core Metrics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Definition</th><th>Initial Target</th></tr></thead><tbody><tr><td>Verified Task Success</td><td>Proportion of tasks that pass the verifier</td><td>Stage 1 ≥ 70%</td></tr><tr><td>Human Minutes / Verified Task</td><td>Human minutes per effectively completed task</td><td>≥ 30% decrease relative to baseline</td></tr><tr><td>Interruptions / Verified Task</td><td>Number of interruptions per task</td><td>≤ 1.0</td></tr><tr><td>Recovery Rate</td><td>Proportion recovered after crash/network loss/restart</td><td>≥ 95%</td></tr><tr><td>Duplicate Side Effects</td><td>Duplicate side effects under fault injection</td><td>0 / 200</td></tr><tr><td>Unsafe Action Rate</td><td>Unauthorized high-risk actions</td><td>0</td></tr><tr><td>Token / Verified Success</td><td>Tokens per effective completion</td><td>Continuously decreasing</td></tr><tr><td>Cost / Verified Success</td><td>Comprehensive cost per effective completion</td><td>Explainable and controllable</td></tr><tr><td>Memory Precision</td><td>Recalled memories are genuinely relevant and correct</td><td>≥ 90%</td></tr><tr><td>Skill Regression</td><td>Promoted skills cause degradation on old tasks</td><td>0 severe regressions</td></tr></tbody></table><p>Target values are early engineering thresholds, not marketing promises, and must be updated with real data.</p><h3 id="baseline-comparison" tabindex="-1">Baseline Comparison <a class="header-anchor" href="#baseline-comparison" aria-label="Permalink to &quot;Baseline Comparison&quot;">​</a></h3><p>Compare at least:</p><ol><li>Fully manual;</li><li>Direct use of Codex;</li><li>The current version of Hearth;</li><li>Alternative routes or skill versions of Hearth.</li></ol><p>Compare success rate, human minutes, interruptions, tokens, latency, cost, and failure recovery, not just output text.</p><h3 id="verifiers" tabindex="-1">Verifiers <a class="header-anchor" href="#verifiers" aria-label="Permalink to &quot;Verifiers&quot;">​</a></h3><ul><li>Code: tests, type checks, diff, CI;</li><li>Documents: structure, references, formatting, user acceptance;</li><li>Email: recipients, facts, tone, send approval, Receipt;</li><li>Web: DOM/accessibility state, screenshots, final state;</li><li>Desktop: accessibility tree, screenshots, target state;</li><li>Research: sources and citations;</li><li>Data: schema, row counts, sampling, reconciliation, reproduction scripts;</li><li>Side effects: idempotency keys, Receipt, reconciliation.</li></ul><h3 id="trajectory-replay-and-fault-injection" tabindex="-1">Trajectory Replay and Fault Injection <a class="header-anchor" href="#trajectory-replay-and-fault-injection" aria-label="Permalink to &quot;Trajectory Replay and Fault Injection&quot;">​</a></h3><p>Historical trajectories should be replayable, support route switching, model/executor substitution, and result comparison. Fault injection must cover at least: process crashes, network interruptions, timeouts, duplicate delivery, disk full, provider rate limiting/authentication expiry, device offline, uncertain external results, approval expiry, and memory/cache invalidation.</p><h3 id="security-and-red-team-evaluation" tabindex="-1">Security and Red Team Evaluation <a class="header-anchor" href="#security-and-red-team-evaluation" aria-label="Permalink to &quot;Security and Red Team Evaluation&quot;">​</a></h3><p>The red team must attempt to make the system exceed authority, leak secrets, duplicate side effects, bypass approvals, poison memory, expand skill permissions, and exploit devices. Evaluation results must feed into release gates, not sit in an appendix.</p><h3 id="statistics-and-evaluation-discipline" tabindex="-1">Statistics and Evaluation Discipline <a class="header-anchor" href="#statistics-and-evaluation-discipline" aria-label="Permalink to &quot;Statistics and Evaluation Discipline&quot;">​</a></h3><ul><li>Define metrics and samples in advance;</li><li>Do not use averages to mask the collapse of a task family;</li><li>Retain failure and rejection samples;</li><li>Evaluation sets must not be used for skill training;</li><li>Distinguish statistical significance from product meaningfulness;</li><li>Record models, executors, prompts, tools, and versions;</li><li>Re-run baselines after changes to avoid &quot;comparing only against old versions.&quot;</li></ul><h3 id="stage-release-gates" tabindex="-1">Stage Release Gates <a class="header-anchor" href="#stage-release-gates" aria-label="Permalink to &quot;Stage Release Gates&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Stage</th><th>Must Prove</th></tr></thead><tbody><tr><td>Stage 0</td><td>Clickable end-to-end prototype, 12 acceptable tasks, core protocols and threat model</td></tr><tr><td>Stage 1</td><td>MVP usable daily in the browser; recoverable, approvable, no duplicate side effects, Codex tasks acceptable</td></tr><tr><td>Stage 2</td><td>Real email/calendar/document/web tasks can be completed, tokens controllable</td></tr><tr><td>Stage 3</td><td>GUI can be taken over, failures recoverable, no exceeding authority</td></tr><tr><td>Stage 4</td><td>Proactive tasks do not cause notification fatigue, approvals and security auditable</td></tr><tr><td>Stage 5</td><td>Memory can be corrected/forgotten, skills can be evaluated/rolled back</td></tr><tr><td>Stage 6</td><td>Multi-device consistency, offline recovery, migration and revocation reliable</td></tr></tbody></table><h3 id="evaluation-anti-patterns" tabindex="-1">Evaluation Anti-Patterns <a class="header-anchor" href="#evaluation-anti-patterns" aria-label="Permalink to &quot;Evaluation Anti-Patterns&quot;">​</a></h3><ul><li>Looking only at demos and screenshots;</li><li>Testing only the success path;</li><li>Counting only model output without verifying side effects;</li><li>Using synthetic tasks instead of real tasks;</li><li>Treating token reduction as the sole goal;</li><li>Evaluation sets contaminated by skill training;</li><li>Failure samples deleted;</li><li>Using averages to mask the collapse of a task family;</li><li>Self-assessment passing;</li><li>No security regression tests;</li><li>Advancing stages with &quot;we&#39;ll add evaluation later.&quot;</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Security and evaluation are not cleanup work for Stage 6. Stage 0 must already have a threat model and task set, and Stage 1 must already have real task acceptance, recovery, and side-effect drills for the MVP; each subsequent executor expansion must expand the security and evaluation surface in sync.</p>',32)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
